previewCss:
.darma-loader-darma-b8-blooming-flower { --accent: var(--loader-color, #ec4899); --accent-2: var(--loader-secondary-color, #a855f7); width: var(--loader-size, 88px); height: var(--loader-size, 88px); position: relative; }
.darma-loader-darma-b8-blooming-flower span { position: absolute; left: 50%; top: 50%; width: 30%; height: 46%; margin-left: -15%; margin-top: -46%; transform-origin: 50% 100%; border-radius: 50% 50% 50% 50% / 70% 70% 30% 30%; background: linear-gradient(var(--accent), var(--accent-2)); animation: darma-loader-darma-b8-blooming-flower-bloom calc(var(--loader-speed, 1s) * 2) ease-in-out infinite; }
.darma-loader-darma-b8-blooming-flower span:nth-child(1) { transform: rotate(0deg); animation-delay: 0s; }
.darma-loader-darma-b8-blooming-flower span:nth-child(2) { transform: rotate(60deg); animation-delay: calc(var(--loader-speed, 1s) * .1); }
.darma-loader-darma-b8-blooming-flower span:nth-child(3) { transform: rotate(120deg); animation-delay: calc(var(--loader-speed, 1s) * .2); }
.darma-loader-darma-b8-blooming-flower span:nth-child(4) { transform: rotate(180deg); animation-delay: calc(var(--loader-speed, 1s) * .3); }
.darma-loader-darma-b8-blooming-flower span:nth-child(5) { transform: rotate(240deg); animation-delay: calc(var(--loader-speed, 1s) * .4); }
.darma-loader-darma-b8-blooming-flower span:nth-child(6) { transform: rotate(300deg); animation-delay: calc(var(--loader-speed, 1s) * .5); }
@keyframes darma-loader-darma-b8-blooming-flower-bloom { 0%, 100% { scale: .3; opacity: .4; } 50% { scale: 1; opacity: .9; } }

